namespace ghidra.feature.vt.gui.task;



using ghidra.feature.vt.api.main;
using ghidra.util.task;

public class TagMarkupItemTask : VtTask {

	protected List<VTMarkupItem> markupItems;
	protected VTMarkupItemConsideredStatus tag;

	public TagMarkupItemTask(VTSession session, List<VTMarkupItem> markupItems,
			VTMarkupItemConsideredStatus tag) : this(tag.name() + " Markup Items", session, markupItems, tag)
    {
	}

	protected TagMarkupItemTask(string title, VTSession session, List<VTMarkupItem> markupItems,
			VTMarkupItemConsideredStatus tag) : base(title, session)
    {
		this.markupItems = markupItems;
		this.tag = tag;
	}

	/* @Override */
	protected bool doWork(TaskMonitor monitor)
    {
		monitor.initialize(markupItems.size());
		foreach (VTMarkupItem markupItem in markupItems) {
			monitor.checkCancelled();
			markupItem.setConsidered(tag);
			monitor.incrementProgress(1);
		}
		return true;
	}
}
